$f = 'c:\Users\adamm\dev\nervosys\os\AetherVM\crates\hv2-api\src\middleware.rs'
$c = [System.IO.File]::ReadAllText($f)
$n = [char]10
$c = $c.Replace("//! | Fingerprint      | ``X-Request-Fingerprint`` hash     | Off     |" + $n + "//! | API Key Auth     | ``Authorization: Bearer <key>``    | Off     |", "//! | Fingerprint      | ``X-Request-Fingerprint`` hash     | Off     |" + $n + "//! | Response Signing | ``X-Response-Signature`` HMAC      | Off     |" + $n + "//! | API Key Auth     | ``Authorization: Bearer <key>``    | Off     |")
$c = $c.Replace("    pub fingerprint: FingerprintConfig," + $n + "    /// Enable JSON 404 fallback for unmatched routes.", "    pub fingerprint: FingerprintConfig," + $n + "    /// Enable HMAC-SHA256 response signing." + $n + "    pub enable_response_signing: bool," + $n + "    /// Response signing configuration." + $n + "    pub response_signing: ResponseSigningConfig," + $n + "    /// Enable JSON 404 fallback for unmatched routes.")
$c = $c.Replace("            enable_fingerprint: false," + $n + "            fingerprint: FingerprintConfig::default()," + $n + "            enable_fallback: true,", "            enable_fingerprint: false," + $n + "            fingerprint: FingerprintConfig::default()," + $n + "            enable_response_signing: false," + $n + "            response_signing: ResponseSigningConfig::default()," + $n + "            enable_fallback: true,")
$c = $c.Replace("            enable_fingerprint: false," + $n + "            fingerprint: FingerprintConfig::default()," + $n + "            enable_fallback: false,", "            enable_fingerprint: false," + $n + "            fingerprint: FingerprintConfig::default()," + $n + "            enable_response_signing: false," + $n + "            response_signing: ResponseSigningConfig::default()," + $n + "            enable_fallback: false,")
